def render_host_listing_notice(tier='pro'):
    limit = 6 if tier == 'starter' else 20
    if tier == 'starter':
        extra = 'Need coverage for more than 6 active tables? Choose <a href="/pay/host_pro" style="color:#c5eddf;text-decoration:underline">Host</a> for up to 20 active tables.'
    else:
        extra = 'Need coverage for more than 20 tables? Contact us in <button type="button" data-open-live-chat style="display:inline;padding:0;border:0;min-height:0;background:none;color:#c5eddf;font:inherit;text-decoration:underline;cursor:pointer">Live Chat</button> or on <a href="https://t.me/tableradar" target="_blank" rel="noopener noreferrer" style="color:#c5eddf;text-decoration:underline">Telegram @tableradar</a> to discuss additional coverage.'
    return f'<aside class="tr-host-listing-notice" aria-label="Host listing conditions" style="margin:18px 0;padding:16px 18px;border:1px solid #a8d8c466;border-left:3px solid #a8d8c4;border-radius:12px;background:#a8d8c410;font-size:13px;line-height:1.65;overflow-wrap:anywhere"><strong style="color:#d3f5e3">* Host listing conditions</strong><div style="margin-top:7px">Standard coverage includes up to <strong>{limit} active tables per club</strong>, with blinds of <strong>$0.50/$1 or higher</strong>. An <strong>active table has at least one seated player</strong>; an open but empty table does not count as active. If your club has more than {limit} active tables, we prioritise eligible tables with higher blinds and more seated players. <strong>Heads-up (one-on-one) tables are not listed.</strong></div><div style="margin-top:7px">{extra}</div></aside>'
